import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div className="component-preview relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout">
      {children}
    </div>
  );
}

import { cn } from "@/registry/erbium/lib/erbium-utils";

import { Slider } from "@/registry/erbium/ui/slider";

type SliderProps = React.ComponentProps<typeof Slider>;

export default function SliderDemo({ className, ...props }: SliderProps) {
  return (
    <Slider
      defaultValue={[50]}
      max={100}
      step={1}
      className={cn("w-[60%]", className)}
      {...props}
    />
  );
}

import * as React from "react";

import { Field, FieldLabel } from "@/registry/erbium/ui/field";
import { Slider } from "@/registry/erbium/ui/slider";

export function SliderControlled() {
  const [value, setValue] = React.useState([0.3, 0.7]);

  return (
    <Field className="mx-auto max-w-xs gap-3">
      <div className="flex items-center justify-between gap-2">
        <FieldLabel>Temperature</FieldLabel>
        <span className="text-sm text-muted-foreground">{value.join(", ")}</span>
      </div>
      <Slider
        value={value}
        onValueChange={(value) => setValue(value as number[])}
        min={0}
        max={1}
        step={0.1}
      />
    </Field>
  );
}

import { Slider } from "@/registry/erbium/ui/slider";

export function SliderMultiple() {
  return (
    <Slider defaultValue={[10, 20, 70]} max={100} step={10} className="mx-auto w-full max-w-xs" />
  );
}

import { Slider } from "@/registry/erbium/ui/slider";

export function SliderRange() {
  return <Slider defaultValue={[25, 50]} max={100} step={5} className="mx-auto w-full max-w-xs" />;
}

import { Slider } from "@/registry/erbium/ui/slider";

export function SliderVertical() {
  return (
    <div className="mx-auto flex w-full max-w-xs items-center justify-center gap-6">
      <Slider defaultValue={[50]} max={100} step={1} orientation="vertical" className="h-40" />
      <Slider defaultValue={[25]} max={100} step={1} orientation="vertical" className="h-40" />
    </div>
  );
}

