const MultipleThumbsSource = "import { SliderMultiple } from \"../examples/upstream/slider-multiple\";\n\nconst Example = () => <SliderMultiple />;\n\nexport default Example;\n";

const meta = {
  component: Slider,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "An input where the user selects a value from within a given range.\n\n**Import:** `@/registry/erbium/ui/slider`\n\n## Usage\n\n```tsx\nimport { Slider } from \"@/registry/erbium/ui/slider\";\n```\n\n```tsx\n<Slider defaultValue={[33]} max={100} step={1} />\n```\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Slider](https://base-ui.com/react/components/slider)",
      },
    },
  },
} satisfies Meta<typeof Slider>;

export default { ...meta, title: "Inputs & forms/Slider",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

