    step: { control: "number" },
    disabled: { control: "boolean" },
    defaultValue: { control: "object" },
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

